-- Génère baseline.sql (structure seule) depuis un projet de référence, en LECTURE SEULE. Ne lit aucune donnée.
with t as (select c.oid, c.relname, c.relrowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r'),
seqs as (select 10 o, c.relname k, format('create sequence if not exists public.%I;', c.relname) s from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S' and not exists (select 1 from pg_depend d where d.objid=c.oid and d.deptype='i')),
tabs as (select 20 o, t.relname k, format('create table if not exists public.%I (%s);', t.relname, string_agg(format('%I %s%s%s%s', a.attname, format_type(a.atttypid,a.atttypmod),
   case when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' else '' end,
   case when ad.adbin is not null and a.attgenerated='' then ' default '||pg_get_expr(ad.adbin,ad.adrelid) else '' end,
   case when a.attnotnull then ' not null' else '' end), ', ' order by a.attnum)) s
  from t join pg_attribute a on a.attrelid=t.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef ad on ad.adrelid=t.oid and ad.adnum=a.attnum group by t.relname),
seqown as (select 25 o, c.relname k, format('alter sequence public.%I owned by public.%I.%I;', c.relname, tt.relname, a.attname) s from pg_class c join pg_depend d on d.objid=c.oid and d.deptype='a' join pg_class tt on tt.oid=d.refobjid join pg_attribute a on a.attrelid=tt.oid and a.attnum=d.refobjsubid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='S'),
cons as (select case when co.contype='f' then 40 else 30 end o, t.relname||co.conname k, format('alter table public.%I add constraint %I %s;', t.relname, co.conname, pg_get_constraintdef(co.oid)) s from pg_constraint co join t on t.oid=co.conrelid where co.contype in ('p','u','c','f','x')),
idx as (select 50 o, i.relname k, pg_get_indexdef(i.oid)||';' s from pg_index x join pg_class i on i.oid=x.indexrelid join t on t.oid=x.indrelid where not exists (select 1 from pg_constraint co where co.conindid=i.oid)),
fn as (select 60 o, p.proname||p.oid k, pg_get_functiondef(p.oid)||';' s from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in ('f','p')),
fnacl as (select 65 o, p.proname||p.oid k, format('revoke all on function %s from public, anon, authenticated;', p.oid::regprocedure)||coalesce((select string_agg(format(' grant execute on function %s to %s;', p.oid::regprocedure, case when e.grantee=0 then 'public' else quote_ident(r.rolname) end),'') from aclexplode(p.proacl) e left join pg_roles r on r.oid=e.grantee where e.privilege_type='EXECUTE' and (e.grantee=0 or r.rolname in ('anon','authenticated','service_role'))),'') s from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proacl is not null),
trg as (select 70 o, tg.tgname k, pg_get_triggerdef(tg.oid)||';' s from pg_trigger tg join t on t.oid=tg.tgrelid where not tg.tgisinternal),
rls as (select 80 o, relname k, format('alter table public.%I enable row level security;', relname) s from t where relrowsecurity),
pol as (select 85 o, tablename||policyname k, format('create policy %I on public.%I as %s for %s to %s%s%s;', policyname, tablename, permissive, cmd, array_to_string(roles, ', '), case when qual is not null then ' using ('||qual||')' else '' end, case when with_check is not null then ' with check ('||with_check||')' else '' end) s from pg_policies where schemaname='public'),
tacl as (select 90 o, t.relname k, format('revoke all on table public.%I from anon, authenticated;', t.relname)||coalesce((select string_agg(format(' grant %s on table public.%I to %I;', g.privs, t.relname, g.grantee),'') from (select grantee, string_agg(privilege_type, ', ') privs from information_schema.role_table_grants where table_schema='public' and table_name=t.relname and grantee in ('anon','authenticated') group by grantee) g),'') s from t)
select string_agg(s, E'\n' order by o, k) ddl from (select * from seqs union all select * from tabs union all select * from seqown union all select * from cons union all select * from idx union all select * from fn union all select * from fnacl union all select * from trg union all select * from rls union all select * from pol union all select * from tacl) x;
